-- Print analytics from the label app. Owned by the label app (not a zenx-pos table).
-- One row per product per print. The browser sends rows at logout / end of day; log_uid is
-- generated by the browser so a resent batch is ignored instead of double-counted.
CREATE TABLE IF NOT EXISTS label_print_logs (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  log_uid VARCHAR(64) NOT NULL,
  client_id BIGINT UNSIGNED NOT NULL,
  client_user_id BIGINT UNSIGNED NOT NULL,
  printed_at DATETIME NOT NULL COMMENT 'UTC',
  method VARCHAR(10) NOT NULL COMMENT 'PRN | BROWSER | PDF',
  status VARCHAR(20) NOT NULL COMMENT 'SPOOLED | UNCONFIRMED | SENT_TO_BROWSER',
  printer_name VARCHAR(255) NULL,
  template_ref VARCHAR(64) NULL,
  template_name VARCHAR(255) NULL,
  product_ref VARCHAR(64) NOT NULL,
  product_code VARCHAR(255) NULL,
  product_name VARCHAR(255) NULL,
  quantity INT UNSIGNED NOT NULL,
  expiry_date DATE NULL COMMENT 'Expiry printed; NULL when left off',
  received_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY label_print_logs_uid_unique (log_uid),
  KEY label_print_logs_client_printed (client_id, printed_at)
);
